组合模式（Composite Pattern）
组合模式是一种结构型设计模式，它允许你将对象组合成树状结构，以表示“部分-整体”的层次结构。这种模式使得用户可以一致地对待单个对象和对象组合。
特点：
部分-整体层次结构：可以包含其他组合或叶节点，形成树状结构。
一致性：客户端代码可以一致地处理组合结构和叶节点。
优点：
简化了客户端代码，客户端可以统一处理组合结构和对象。
更好的层次结构表示，易于扩展和维护。
缺点：
设计较复杂，需要合理地设计组件的接口和类。
应用场景：
文件系统：
文件系统中的文件和文件夹可以形成树状结构，其中文件夹可以包含文件和其他文件夹。
组织结构：
公司的组织结构可以表示为树状结构，其中每个部门可以包含员工和其他子部门。
GUI 组件：
在图形用户界面开发中，组件可以包含其他组件，形成复杂的界面结构。
分布式系统：
在分布式系统中，资源可以组合成树状结构，以方便管理和访问。
企业资源规划（ERP）：
ERP 系统中，产品可以由多个部件组成，部件又可以进一步分解为子部件。
// 定义Component接口，作为组合中对象的一致性协议
type
Component
interface
{
Operation()
// 执行操作的方法
Add(Component)
// 向组合中添加子节点的方法
Remove(Component)
// 从组合中移除子节点的方法
GetChild(
int
) Component
// 根据索引获取子节点的方法
}
// 定义Leaf结构体，表示组合中的叶节点
type
Leaf
struct
{
name
string
}
// Leaf实现Component接口的Operation方法
func
(l *Leaf)
Operation() {
fmt.Println(
"Leaf:"
, l.name)
}
// Leaf实现Component接口的Add方法，叶节点不能有子节点，因此这里可以不实现或抛出错误
func
(l *Leaf)
Add(c Component) {
fmt.Println(
"Cannot add to a leaf"
)
}
// Leaf实现Component接口的Remove方法，叶节点不能有子节点，因此这里可以不实现或抛出错误
func
(l *Leaf)
Remove(c Component) {
fmt.Println(
"Cannot remove from a leaf"
)
}
// Leaf实现Component接口的GetChild方法，叶节点没有子节点，因此这里返回nil
func
(l *Leaf)
GetChild(i
int
) Component {
return
nil
}
// 定义Composite结构体，表示组合中的容器节点
type
Composite
struct
{
name
string
Children []Component
// 存储子节点的列表
}
// Composite实现Component接口的Operation方法
func
(c *Composite)
Operation() {
fmt.Println(
"Composite:"
, c.name)
for
_, child :=
range
c.Children {
child.Operation()
// 递归调用子节点的Operation方法
}
}
// Composite实现Component接口的Add方法，向Children列表中添加子节点
func
(c *Composite)
Add(component Component) {
c.Children =
append
(c.Children, component)
}
// Composite实现Component接口的Remove方法，从Children列表中移除子节点
func
(c *Composite)
Remove(component Component) {
for
i, child :=
range
c.Children {
if
child == component {
c.Children =
append
(c.Children[:i], c.Children[i+
1
:]...)
break
}
}
}
// Composite实现Component接口的GetChild方法，根据索引获取子节点
func
(c *Composite)
GetChild(i
int
) Component {
if
i <
0
|| i >=
len
(c.Children) {
return
nil
// 索引超出范围，返回nil
}
return
c.Children[i]
}
func
main
()
{
// 创建叶节点
leafA := &Leaf{name:
"Leaf A"
}
leafB := &Leaf{name:
"Leaf B"
}
// 创建组合节点
composite := &Composite{name:
"Composite Root"
}
composite.Add(leafA)
// 向组合中添加叶节点A
composite.Add(leafB)
// 向组合中添加叶节点B
// 执行组合节点的操作
composite.Operation()
}
